using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BInterceptSourceTests {
  internal static BCarriageBuffDefinitions Defs()=>(BCarriageBuffDefinitions)typeof(BCarriageBuffTests).GetMethod("Definitions",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);
  internal static JObject Supplier()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-intercept-ability-traces-20261004.json"));
  internal static JObject Sample(int n=4)=>(JObject)Supplier()["acceptedTimingSamples"][n].DeepClone();
  internal static JObject Trust(JObject p){var x=p["originalSource"]["originalSource"];return new JObject(new[]{"origin","nativeContextId","seedHash","sourceHash","nodeId","visitDepth","priorSourceHash"}.Select(k=>new JProperty(k,x[k].DeepClone())));}
  [Test] public void ReceivedV3TimingReaderRetainsExactAcceptedJournalAndOriginalTrust(){var p=Sample();var type=typeof(BScoutGunnerDefinitionSnapshot).Assembly.GetType("LastRail.Run.BInterceptTimingSnapshot");Assert.NotNull(type,"Missing strict v3 accepted timing reader");var value=type.GetMethod("Read").Invoke(null,new object[]{p,(string)p["sourceHash"],Trust(p),Defs()});Assert.IsTrue(JToken.DeepEquals(p,(JObject)type.GetMethod("Capture").Invoke(value,null)));}
  internal static BInterceptTimingSnapshot Read(JObject p)=>BInterceptTimingSnapshot.Read(p,(string)p["sourceHash"],Trust(p),Defs());
  static void Rehash(JObject p,string name){p.Remove(name);p[name]=BDirectAttackInput.Digest(p).Substring(7);}
  [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)][TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)][TestCase(8)][TestCase(9)] public void AllOriginalRankAndHolderSamplesRestoreWithoutCurrentRankLookup(int n){var p=Sample(n);var s=Read(p);Assert.IsTrue(JToken.DeepEquals(p,s.Capture()));Assert.AreEqual(2000,s.StepMicroseconds);p["timing"]["totalHasteBps"]=0;Assert.IsFalse(JToken.DeepEquals(p,s.Capture()));}
  [TestCase("holder")][TestCase("run")][TestCase("context")][TestCase("mixed")][TestCase("applied")][TestCase("duplicate")][TestCase("timing")][TestCase("extra")][TestCase("buff")][TestCase("hash")]
  public void RehashedInvalidTimingOrOriginIsRejected(string fault){var p=Sample();var t=(JObject)p["timing"];if(fault=="holder")t["operatorId"]="op_sable";if(fault=="run")t["runId"]="foreign";if(fault=="context")t["nativeContextId"]="foreign";if(fault=="mixed"||fault=="applied"||fault=="duplicate"){var term=new JObject{["sourceId"]=fault=="duplicate"?t["buffSnapshot"]["actions"][0]["source"]["sourceId"].DeepClone():new JValue("original"),["group"]=fault=="mixed"?"ATTACK_SPEED":"INTERCEPTION_HASTE",["valueBps"]=0,["appliedVersion"]=fault=="applied"?new JValue("old"):JValue.CreateNull()};((JArray)t["originalHasteSources"]).Add(term);}if(fault=="timing")t["phases"]["preparation"]["ticks"]="98";if(fault=="extra")t["eligible"]=true;if(fault=="buff")t["buffSnapshot"]["actions"][0]["source"]["interceptionHasteBps"]=0;Rehash(t,"timingHash");Rehash(p,"sourceHash");if(fault=="hash")Assert.Throws<ArgumentException>(()=>BInterceptTimingSnapshot.Read(p,new string('0',64),Trust(p),Defs()));else Assert.Throws<ArgumentException>(()=>Read(p));}
  internal static BDirectAttackBasicLoopBinding Binding(JObject p,int distance=6000,long nativeStep=0){var source=Read(p).OriginalSource;var old=BGunnerInterceptRuntimeTests.Kyle(source,distance,"BCB03");var input=old.Composition.Attack.Capture();var departure=(JObject)p["timing"]["buffSnapshot"]["departure"];string car=(string)departure["cars"][0]["instanceId"];var form=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot(car,"op_kyle")});input["formation"]=form.Capture();((JArray)input["entities"]).Single(e=>(string)e["id"]=="car0")["id"]=car;input["stepTimeSpanTicks"]=(nativeStep==0?(long)p["timing"]["stepUs"]:nativeStep)*10;var flags=BindingFlags.Static|BindingFlags.NonPublic;var profile=(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Owned",flags).Invoke(null,null);profile["accountId"]=source.OriginalSource.Capture()["origin"]["accountId"].DeepClone();var def=(CombatDefinitionIndex)typeof(BDirectAttackBasicLoopTests).GetMethod("Definition",flags).Invoke(null,null);var attack=BDirectAttackInput.ReadGunnerInterceptLocalRuntime(input,BDirectAttackInput.Digest(input),form,profile,BDirectAttackInput.Digest(profile),def,source.OriginalSource);var c=old.Composition.Capture();c["attackInputHash"]=attack.OriginalHash;c["departure"]=departure.DeepClone();c["initial"]=p["timing"]["buffSnapshot"]["initial"].DeepClone();var composition=new BDirectAttackBuffBinding(attack,Defs(),c,BDirectAttackInput.Digest(c));var routes=old.Capture();routes["compositionHash"]=composition.OriginalHash;return new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));}
  internal static BWaveBoardingLocalPaths Paths(BDirectAttackInput input){JObject Side(string id)=>new JObject{["socketId"]=id,["approachPathMm"]=new JArray(new JArray(0,0,0),new JArray(100,0,0)),["climbPathMm"]=new JArray(new JArray(100,0,0),new JArray(100,100,0))};var p=new JObject{["version"]=BWaveBoardingLocalPaths.Version,["provenance"]="EXPLICIT_LOCAL_GRAPH_FIXTURE_NOT_ORDINARY_RUNTIME",["inputHash"]=input.OriginalHash,["carriages"]=new JArray(input.Formation.Slots.Select((c,i)=>new JObject{["carriageId"]=c.CarriageId,["slot"]=i,["left"]=Side("left"+i),["right"]=Side("right"+i)}))};return BWaveBoardingLocalPaths.Read(p,BDirectAttackInput.Digest(p),input);}
  [Test] public void ActualClockMismatchRejectsBeforeAnyReservationOrBasicCost(){var p=Sample();var receipt=Read(p);var b=Binding(p,6000,10000);var s=BDirectAttackBasicLoop.CreateInterceptSourceRuntime(b,receipt.OriginalSource,Paths(b.Composition.Attack),10000);s.Advance("launch",74000000,740);string shot=(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["id"];var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.AcceptInterceptionSource("bad-step",shot,receipt));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void OriginalAcceptedReceiptCancelReplayAndRestoreCannotReacceptOrRestartRecovery(){var p=Sample();var r=Read(p);var b=Binding(p);var paths=Paths(b.Composition.Attack);var s=BDirectAttackBasicLoop.CreateInterceptSourceRuntime(b,r.OriginalSource,paths,10000);s.Advance("launch",74000000,3700);string shot=(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["id"];var result=s.AcceptInterceptionSource("accepted",shot,r);var accepted=s.Capture();Assert.AreSame(result,s.AcceptInterceptionSource("accepted",shot,r));Assert.IsTrue(JToken.DeepEquals(accepted,s.Capture()));Assert.Throws<ArgumentException>(()=>s.AcceptInterceptionSource("second-command",shot,r));s.Advance("spent",1000000,50);s.CancelLocalGunnerShot("cancel",shot);var action=s.Capture()["gunnerIntercept"]["interception"]["actions"][0];Assert.AreEqual(3924,(long)action["endTick"]);Assert.AreEqual(3924,(long)s.Capture()["state"]["direct"]["next"]["op_kyle"]);Assert.IsTrue(JToken.DeepEquals(p,action["timingSource"]));s.CancelLocalGunnerShot("cancel-again",shot);Assert.AreEqual(3924,(long)s.Capture()["gunnerIntercept"]["interception"]["actions"][0]["endTick"]);var cache=s.Capture();var restored=BDirectAttackBasicLoop.RestoreInterceptSourceRuntime(cache,BDirectAttackInput.Digest(cache),b,r.OriginalSource,paths,10000);s.Advance("recover",4000000,200);restored.Advance("recover",4000000,200);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));Assert.AreEqual("DONE",(string)s.Capture()["gunnerIntercept"]["interception"]["actions"][0]["phase"]);cache["gunnerIntercept"]["interception"]["actions"][0]["timingSource"]["timing"]["totalHasteBps"]=0;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreInterceptSourceRuntime(cache,BDirectAttackInput.Digest(cache),b,r.OriginalSource,paths,10000));}
  [Test] public void ReceivedReceiptBindsOriginalNativeClockAndSingleReservation(){var p=Sample();var receipt=Read(p);var b=Binding(p);var factory=typeof(BDirectAttackBasicLoop).GetMethod("CreateInterceptSourceRuntime");Assert.NotNull(factory,"Missing source-bound native factory");var s=(BDirectAttackBasicLoop)factory.Invoke(null,new object[]{b,receipt.OriginalSource,Paths(b.Composition.Attack),10000});s.Advance("launch",74000000,3700);var shot=(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["id"];var accept=typeof(BDirectAttackBasicLoop).GetMethod("AcceptInterceptionSource");Assert.NotNull(accept);accept.Invoke(s,new object[]{"accept",shot,receipt});var action=s.Capture()["gunnerIntercept"]["interception"]["actions"][0];Assert.AreEqual(3797,(long)action["readyTick"]);Assert.AreEqual(3971,(long)action["endTick"]);Assert.IsTrue(JToken.DeepEquals(p,action["timingSource"]));s.Advance("contact",2500000,125);Assert.AreEqual("INTERCEPTED",(string)s.Capture()["gunnerIntercept"]["projectiles"][0]["terminal"]);}
 }
}
